	manifest := `{
	  "terraform_source_bundle": 1,
	  "packages": [
	    {
	      "source": "git::https://example.com/root.git",
	      "local": "root",
	      "meta": {}
	    }
	  ],
	  "registry": []
	}`
	if err := os.WriteFile(filepath.Join(dir, "terraform-sources.json"), []byte(manifest), 0o644); err != nil {
		t.Fatalf("failed to write bundle manifest: %s", err)
